// ============================================================
//  SCHOOL RESULT MANAGEMENT SYSTEM  (Class 11 Final Project)
//  Uses: struct, vector, map, functions, strings, loops,
//        switch, if-else, formatted output, sorting
// ============================================================
#include <iostream>

#include <iomanip>
#include <string>
#include <vector>
#include <map>
#include <algorithm>
using namespace std;

const int SUBJECTS = 5;
const string SUBJECT_NAMES[SUBJECTS] = {"English", "Physics", "Chemistry",
"Maths", "CompSci"};

struct Student {
    int roll;
    string name;
    int marks[SUBJECTS];
    int total;
    float percent;
    char grade;
};

// ---------- helper functions ----------

void line(char ch = '-', int n = 60) {
    for (int i = 0; i < n; i++) cout << ch;
    cout << endl;
}

char findGrade(float p) {
    if (p >= 90) return 'A';
    else if (p >= 75) return 'B';
    else if (p >= 60) return 'C';
    else if (p >= 33) return 'D';
    else return 'F';
}

void calculate(Student &s) {          // call by reference
    s.total = 0;
    for (int i = 0; i < SUBJECTS; i++)
        s.total += s.marks[i];
    s.percent = s.total / (float)SUBJECTS;
    s.grade = findGrade(s.percent);
}

int readMark(const string &subject) {   // input validation
    int m;
    do {
        cout << "  " << subject << " (0-100): ";
        cin >> m;
        if (m < 0 || m > 100) cout << "  Invalid! Enter again." << endl;
    } while (m < 0 || m > 100);
    return m;
}

int findIndex(const vector<Student> &list, int roll) {   // linear search
    for (int i = 0; i < (int)list.size(); i++)
        if (list[i].roll == roll) return i;
    return -1;
}

// ---------- menu operations ----------

void addStudent(vector<Student> &list) {
    Student s;
    cout << "Roll number: ";
    cin >> s.roll;
    if (findIndex(list, s.roll) != -1) {
        cout << "A student with this roll number already exists." << endl;
        return;
    }
    cin.ignore();
    cout << "Name: ";
    getline(cin, s.name);
    cout << "Enter marks:" << endl;
    for (int i = 0; i < SUBJECTS; i++)
        s.marks[i] = readMark(SUBJECT_NAMES[i]);
    calculate(s);
    list.push_back(s);
    cout << "Student added successfully!" << endl;
}

void showHeader() {
    cout << left << setw(6) << "Roll" << setw(20) << "Name"
         << right << setw(8) << "Total" << setw(10) << "Percent" << setw(8)
<< "Grade" << endl;
    line();
}

void showRow(const Student &s) {
    cout << left << setw(6) << s.roll << setw(20) << s.name
         << right << setw(8) << s.total
         << setw(9) << fixed << setprecision(2) << s.percent << "%"
         << setw(8) << s.grade << endl;
}

void displayAll(const vector<Student> &list) {
    if (list.empty()) { cout << "No records yet." << endl; return; }
    showHeader();
    for (const Student &s : list) showRow(s);
}

void reportCard(const vector<Student> &list) {
    int roll;
    cout << "Enter roll number: ";
    cin >> roll;
    int idx = findIndex(list, roll);
    if (idx == -1) { cout << "Record not found." << endl; return; }

    const Student &s = list[idx];
    line('=');
    cout << "                     REPORT CARD" << endl;
    line('=');
    cout << "Name : " << s.name << "     Roll No: " << s.roll << endl;
    line();
    for (int i = 0; i < SUBJECTS; i++)
        cout << left << setw(15) << SUBJECT_NAMES[i] << right << setw(5) <<
s.marks[i]
             << (s.marks[i] < 33 ? "   (Needs improvement)" : "") << endl;
    line();
    cout << "Total      : " << s.total << " / " << SUBJECTS * 100 << endl;
    cout << "Percentage : " << fixed << setprecision(2) << s.percent << "%"
<< endl;
    cout << "Grade      : " << s.grade << endl;
    cout << "Result     : " << (s.grade == 'F' ? "FAIL" : "PASS") << endl;
    line('=');
}

void updateMarks(vector<Student> &list) {
    int roll;
    cout << "Enter roll number: ";
    cin >> roll;
    int idx = findIndex(list, roll);
    if (idx == -1) { cout << "Record not found." << endl; return; }

    cout << "Subjects: ";
    for (int i = 0; i < SUBJECTS; i++) cout << i + 1 << "." <<
SUBJECT_NAMES[i] << " ";
    cout << endl << "Choose subject number: ";
    int sub;
    cin >> sub;
    if (sub < 1 || sub > SUBJECTS) { cout << "Invalid subject." << endl;
return; }
    list[idx].marks[sub - 1] = readMark(SUBJECT_NAMES[sub - 1]);
    calculate(list[idx]);
    cout << "Marks updated. New percentage: " << fixed << setprecision(2)
         << list[idx].percent << "%" << endl;
}

void deleteStudent(vector<Student> &list) {
    int roll;
    cout << "Enter roll number to delete: ";
    cin >> roll;
    int idx = findIndex(list, roll);
    if (idx == -1) { cout << "Record not found." << endl; return; }
    cout << "Deleted record of " << list[idx].name << "." << endl;
    list.erase(list.begin() + idx);
}

bool byPercent(const Student &a, const Student &b) {
    return a.percent > b.percent;      // higher percentage first
}

void meritList(vector<Student> list) {   // copy, so original order is kept
    if (list.empty()) { cout << "No records yet." << endl; return; }
    sort(list.begin(), list.end(), byPercent);
    cout << "MERIT LIST" << endl;
    cout << setw(4) << "Rank" << "  ";
    showHeader();
    for (int i = 0; i < (int)list.size(); i++) {
        cout << setw(4) << i + 1 << "  ";
        showRow(list[i]);
    }
}

void statistics(const vector<Student> &list) {
    if (list.empty()) { cout << "No records yet." << endl; return; }

    float sum = 0;
    int topIdx = 0, passCount = 0;
    map<char, int> gradeCount;

    for (int i = 0; i < (int)list.size(); i++) {
        sum += list[i].percent;
        if (list[i].percent > list[topIdx].percent) topIdx = i;
        if (list[i].grade != 'F') passCount++;
        gradeCount[list[i].grade]++;
    }

    cout << fixed << setprecision(2);
    cout << "Total students   : " << list.size() << endl;
    cout << "Class average    : " << sum / list.size() << "%" << endl;
    cout << "Topper           : " << list[topIdx].name << " ("
         << list[topIdx].percent << "%)" << endl;
    cout << "Pass percentage  : " << passCount * 100.0 / list.size() << "%"
<< endl;

    cout << "Subject averages :" << endl;
    for (int j = 0; j < SUBJECTS; j++) {
        float subSum = 0;
        for (const Student &s : list) subSum += s.marks[j];
        cout << "   " << left << setw(12) << SUBJECT_NAMES[j] << right
             << subSum / list.size() << endl;
    }

    cout << "Grade distribution:" << endl;
    for (auto g : gradeCount) {
        cout << "   " << g.first << " : ";
        for (int k = 0; k < g.second; k++) cout << "*";
        cout << " (" << g.second << ")" << endl;
    }
}

// ---------- main ----------

int main() {
    vector<Student> students;
    int choice;

    do {
        cout << endl;
        line('=');
        cout << "        SCHOOL RESULT MANAGEMENT SYSTEM" << endl;
        line('=');
        cout << "1. Add student" << endl;
        cout << "2. Display all students" << endl;
        cout << "3. Show report card" << endl;
        cout << "4. Update marks" << endl;
        cout << "5. Delete student" << endl;
        cout << "6. Merit list" << endl;
        cout << "7. Class statistics" << endl;
        cout << "0. Exit" << endl;
        cout << "Enter your choice: ";
        cin >> choice;
        cout << endl;

        switch (choice) {
            case 1: addStudent(students);    break;
            case 2: displayAll(students);    break;
            case 3: reportCard(students);    break;
            case 4: updateMarks(students);   break;
            case 5: deleteStudent(students); break;
            case 6: meritList(students);     break;
            case 7: statistics(students);    break;
            case 0: cout << "Thank you for using the system!" << endl; break;
            default: cout << "Invalid choice. Try again." << endl;
        }
    } while (choice != 0);

    return 0;
}
